{
 "summary": "Lean states the paper's sharp Ehrhart volume inequality: a compact convex set in ℝⁿ (n>0) with nonempty interior, barycenter 0 and interior lattice points exactly {0} has Lebesgue volume at most (n+1)ⁿ/n!. It also states that the simplex (n+1)Δₙ−(1,…,1) has barycenter 0 and volume (n+1)ⁿ/n!, and that a body attaining the bound exists. The statements match the paper. The only caveats are cosmetic: 'normalizedVolume' is plain Lebesgue volume, and the Lean version requires n>0.",
 "glossary": [
  {"decl": "Ehrhart.Space", "line": 10, "plain": "ℝⁿ as Fin n → ℝ with the product Lebesgue measure", "standard_concept": "Euclidean space ℝⁿ", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.standardSimplex", "line": 15, "plain": "{x : xᵢ ≥ 0, Σxᵢ ≤ 1}", "standard_concept": "Δₙ = conv{0,e₁,…,eₙ}", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.centeredSimplex", "line": 21, "plain": "Image of Δₙ under x ↦ (n+1)x − (1,…,1)", "standard_concept": "(n+1)Δₙ − (1,…,1)", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.normalizedVolume", "line": 24, "plain": "Lebesgue measure of K as a real number (toReal)", "standard_concept": "vol(K)", "matches_standard": "yes", "note": "The name suggests a normalization, but it is the plain volume. toReal is harmless for compact K, whose volume is finite."},
  {"decl": "Ehrhart.barycenter", "line": 27, "plain": "(1/vol K)·∫_K x dx", "standard_concept": "center of mass of K", "matches_standard": "yes", "note": "Junk values occur only if vol K = 0 or K is not integrable. The theorems assume nonempty interior and compactness, so this is avoided."},
  {"decl": "Ehrhart.interiorLatticePoints", "line": 30, "plain": "{z ∈ ℤⁿ : z ∈ int K}", "standard_concept": "int(K) ∩ ℤⁿ", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.CenteredBody", "line": 33, "plain": "Compact convex K with nonempty interior, barycenter 0, and int(K) ∩ ℤⁿ = {0}", "standard_concept": "Hypotheses of Theorem 1.1", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.sharpConstant", "line": 41, "plain": "(n+1)ⁿ / n!", "standard_concept": "(n+1)ⁿ/n!", "matches_standard": "yes", "note": ""}
 ],
 "lean_claims": [
  {"theorem": "Ehrhart.SimplexVolume.barycenter_centeredSimplex", "line": 48, "plain": "For every n, the barycenter of (n+1)Δₙ−(1,…,1) is 0."},
  {"theorem": "Ehrhart.SimplexVolume.normalizedVolume_centeredSimplex", "line": 52, "plain": "For n>0, vol((n+1)Δₙ−(1,…,1)) = (n+1)ⁿ/n!."},
  {"theorem": "Ehrhart.SimplexVolume.exists_centeredBody_sharp", "line": 56, "plain": "For n>0 there is a compact convex body K with nonempty interior, barycenter 0, int(K) ∩ ℤⁿ = {0}, and vol(K) = (n+1)ⁿ/n!."},
  {"theorem": "Ehrhart.Volume.ehrhart_volume_inequality_for_sets", "line": 65, "plain": "For n>0 and S ⊂ ℝⁿ convex, compact, with nonempty interior, barycenter 0 and int(S) ∩ ℤⁿ = {0}, vol(S) ≤ (n+1)ⁿ/n!."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.1", "plain": "A full-dimensional compact convex K ⊂ ℝⁿ with barycenter 0 and int(K) ∩ ℤⁿ = {0} has vol(K) ≤ (n+1)ⁿ/n!."},
  {"ref": "Sharpness remark (after Thm 1.1)", "plain": "The simplex (n+1)Δₙ − (1,…,1) has barycenter 0, no other interior lattice point, and volume (n+1)ⁿ/n!."}
 ],
 "coverage": [
  {"paper_ref": "Theorem 1.1", "lean_theorem": "Ehrhart.Volume.ehrhart_volume_inequality_for_sets", "relation": "equivalent", "why": "The hypotheses and conclusion are the same. Lean adds n>0, which is the intended range."},
  {"paper_ref": "Sharpness remark", "lean_theorem": "Ehrhart.SimplexVolume.exists_centeredBody_sharp", "relation": "equivalent", "why": "Lean packages the existence of an extremizer. It is witnessed by the simplex, with the barycenter and volume facts given by the two simplex theorems. The simplex theorems do not themselves state that the simplex has no other interior lattice point; that is carried only inside the existence statement."},
  {"paper_ref": "Sharpness remark (barycenter and volume of the simplex)", "lean_theorem": "Ehrhart.SimplexVolume.barycenter_centeredSimplex", "relation": "equivalent", "why": "Barycenter 0 for the explicit simplex."},
  {"paper_ref": "Sharpness remark (barycenter and volume of the simplex)", "lean_theorem": "Ehrhart.SimplexVolume.normalizedVolume_centeredSimplex", "relation": "equivalent", "why": "Volume equals (n+1)ⁿ/n!."}
 ],
 "flags": [
  {"id": "F1", "category": "other", "severity": "low", "decl": "Ehrhart.normalizedVolume", "line": 24, "paper_ref": "Theorem 1.1", "explanation": "The name suggests a normalized volume such as n!·vol. The definition is plain Lebesgue volume, which matches the paper's vol(K). This is cosmetic only.", "polarity": "n/a", "probe_idea": "example (n : ℕ) (K : Set (Ehrhart.Space n)) : Ehrhart.normalizedVolume K = ((MeasureTheory.volume K).toReal) := rfl"},
  {"id": "F2", "category": "assumption", "severity": "low", "decl": "Ehrhart.Volume.ehrhart_volume_inequality_for_sets", "line": 65, "paper_ref": "Theorem 1.1", "explanation": "The extra hypothesis 0<n excludes n=0. The paper implicitly takes n≥1, so this has no practical effect.", "polarity": "lean weaker", "probe_idea": null}
 ],
 "lint_verdicts": []
}
